// Chapitre 1 du module UE1, Droit du travail : contenu pur.
// La mise en forme appartient au moteur components/chapitre/ChapitreManuscrit.tsx.
//
// Sources de première main : Loi n°015/2002 du 16 octobre 2002 portant Code du
// travail, telle que modifiée par la loi n°16/010 du 15 juillet 2016 (Titre I,
// art. 1 à 7 ; Titre XVI, art. 330 à 334), citée mot pour mot ; Constitution du
// 18 février 2006 (art. 12, 13, 36 à 39, 122, 215). Les faits d'actualité
// (SMIG 2025-2026, propositions de loi 2025-2026, ratifications OIT) sont datés
// et présentés comme tels ; une initiative parlementaire n'est jamais confondue
// avec le droit positif.
import type { Chapitre } from '@/lib/chapitre-types'

const SECTIONS: Chapitre['sections'] = [
  {
    numero: '1.1',
    titre: "Objet, finalité et caractères du droit du travail",
    navLabel: '1.1 Objet et finalité',
    blocs: [
      { type: 'paragraphe', texte: "Le droit du travail est la branche du droit qui régit les rapports individuels et collectifs nés à l'occasion du travail salarié, c'est-à-dire du travail fourni par une personne pour le compte et sous l'autorité d'une autre, moyennant rémunération. Il ne couvre donc ni le travail indépendant de l'artisan ou du commerçant, ni celui du fonctionnaire régi par un statut, ni les prestations bénévoles. En République Démocratique du Congo, il repose sur la loi n°015/2002 du 16 octobre 2002 portant Code du travail, modifiée et complétée par la loi n°16/010 du 15 juillet 2016. Le Code compte seize titres et trois cent trente-quatre articles, du champ d'application (Titre I) aux dispositions transitoires (Titre XVI). Il constitue le socle de référence de l'ensemble de ce manuel, et chaque chapitre en étudie un ou plusieurs titres." },
      { type: 'paragraphe', texte: "Cette branche du droit poursuit une finalité qui la distingue nettement du droit commun des contrats. Le droit civil des obligations postule l'égalité des contractants et laisse à leur volonté le soin de fixer le contenu de l'accord. Le droit du travail organise au contraire une relation structurellement inégale : celle du travailleur, économiquement dépendant de son emploi pour assurer sa subsistance et celle de sa famille, face à l'employeur, qui détient le pouvoir de direction, d'organisation et, en dernier ressort, de rupture du lien contractuel. Le législateur ne s'est pas contenté d'encadrer un échange de prestations ; il a construit, article après article, un dispositif de protection minimale auquel le contrat individuel ne peut déroger que dans un sens plus favorable au travailleur." },
      { type: 'paragraphe', texte: "Cette prémisse permet de trancher un débat récurrent dans la doctrine congolaise : le contrat de travail est-il véritablement négocié entre les parties, ou n'est-il, dans la grande majorité des cas, qu'un contrat d'adhésion que le travailleur accepte en bloc, faute de pouvoir en discuter les termes ? Kapuku (2026) observe que l'égalité juridique proclamée par le droit commun des obligations masque, dans les faits, une inégalité économique structurelle entre l'employeur qui fixe les conditions d'engagement et le travailleur qui les accepte par nécessité. C'est précisément pour corriger ce déséquilibre que le Code du travail impose des règles impératives là où le droit civil se contenterait de règles supplétives. Dans un pays où, selon l'enquête sur les conditions de vie des ménages conduite par l'Institut national de la statistique en 2024-2025, le taux d'emploi moyen s'établit à 55,9 % et où l'agriculture concentre à elle seule 45,7 % des actifs occupés, cette inégalité est encore accentuée par la rareté de l'emploi formel : le candidat à l'embauche négocie rarement, il accepte." },
      { type: 'filet', titre: "Principe de faveur", texte: "La loi fixe un plancher de protection, jamais un plafond. Toute clause du contrat, du règlement d'entreprise ou d'une convention collective qui abaisserait ce plancher est réputée non écrite ; toute clause qui le relève est valable et s'impose à l'employeur. Le Titre IV du Code (art. 37, étudié au chapitre 3) frappe de nullité de plein droit la clause moins favorable au travailleur que la loi." },
      { type: 'paragraphe', texte: "Cette logique protectrice explique pourquoi le droit du travail se lit rarement comme un texte supplétif : la plupart de ses dispositions sont d'ordre public social, c'est-à-dire qu'elles s'imposent indépendamment de la volonté des parties, mais dans un seul sens. On parle d'ordre public *relatif* ou *unilatéral* : la règle interdit de descendre au-dessous du minimum légal, elle n'interdit pas de le dépasser. Un employeur qui accorde trente jours de congé là où la loi en impose douze ne viole rien ; celui qui n'en accorde que dix viole la loi, quand bien même le travailleur aurait signé. Quelques dispositions relèvent en revanche de l'ordre public *absolu* : ni l'employeur ni le travailleur ne peuvent y déroger, même d'un commun accord et même dans un sens apparemment favorable. C'est le cas de l'interdiction du travail forcé (art. 2) ou de l'interdiction des pires formes de travail des enfants (art. 3), qui protègent la personne humaine et non un simple intérêt patrimonial." },
      { type: 'paragraphe', texte: "Cette vocation protectrice n'est pas une invention récente du législateur de 2002. Luwenyema Lulue relevait déjà, dans son Précis de droit du travail zaïrois publié à Kinshasa en 1989, que le droit du travail zaïrois s'était construit sur cette même orientation, héritée pour partie de la législation coloniale du travail et prolongée par les réformes successives de l'État congolais. Le Code de 2002 poursuit ainsi une tradition doctrinale continue, plutôt qu'il ne rompt avec elle. La section suivante en retrace les grandes étapes." },
      { type: 'paragraphe', texte: "Il faut enfin situer le droit du travail dans l'ensemble plus vaste du droit social. Celui-ci regroupe, d'une part, le droit du travail proprement dit (relations individuelles et collectives entre employeurs et travailleurs) et, d'autre part, le droit de la sécurité sociale, qui organise la couverture des risques sociaux (maladie, maternité, accident du travail, vieillesse, charges de famille) par des institutions distinctes de l'employeur. En RDC, le régime général des travailleurs du secteur privé est géré par la Caisse nationale de sécurité sociale (CNSS) en application de la loi n°16/009 du 15 juillet 2016 et du décret n°18/041 du 24 novembre 2018 fixant les taux de cotisation. Ce manuel traite du droit du travail ; il renvoie au chapitre 7 pour l'articulation avec la sécurité sociale, et rappelle dès maintenant que les deux disciplines partagent un vocabulaire commun, à commencer par la définition de la rémunération et celle de la famille du travailleur, toutes deux posées par l'article 7 du Code et expressément rendues applicables aux textes de sécurité sociale." },
      { type: 'carte', titre: "Les trois caractères du droit du travail congolais", liste: [
        "Un droit *protecteur* : il corrige l'inégalité économique des parties par des règles impératives, d'ordre public social, qui ne s'appliquent que dans le sens favorable au travailleur (principe de faveur).",
        "Un droit *évolutif* : ses textes d'application (SMIG, jours fériés, travaux légers, taux de cotisation) sont modifiés indépendamment du Code, et le Code lui-même fait l'objet de propositions de réforme régulières ; le juriste vérifie toujours la version en vigueur.",
        "Un droit *effectif à géométrie variable* : la règle existe pour tous les travailleurs entrant dans le champ de l'article 1er, mais son application dépend de l'inspection du travail, des tribunaux du travail et de la formalisation des relations d'emploi, largement défaillante dans l'économie informelle.",
      ] },
      { type: 'paragraphe', texte: "Comprendre cette finalité en amont conditionne la lecture de tous les chapitres qui suivent, du contrat de travail à la rémunération, en passant par la rupture et le décompte final. Chaque règle technique étudiée dans ce manuel, aussi précise soit-elle, se justifie in fine par cette recherche d'équilibre entre la protection du travailleur et les nécessités de gestion de l'employeur. C'est aussi ce qui explique la méthode d'interprétation propre à la matière : dans le doute, le juge du travail retient le sens le plus favorable au travailleur, et il qualifie les situations d'après les faits, non d'après les mots que les parties ont choisis." },
    ],
  },
  {
    numero: '1.2',
    titre: "Genèse et évolution : de la législation coloniale au Code de 2002 révisé en 2016",
    navLabel: '1.2 Histoire du Code',
    blocs: [
      { type: 'paragraphe', texte: "Le droit du travail congolais est le produit d'une sédimentation d'un siècle. Sa première strate est coloniale. L'industrialisation du Congo belge, avec l'exploitation minière du Katanga et la construction du chemin de fer, a fait apparaître une main-d'œuvre salariée africaine que l'ordre juridique colonial a d'abord traitée par des textes distincts de ceux applicables aux Européens. Le décret du 16 mars 1922 relatif au contrat de travail « entre maîtres civilisés et indigènes » constitue le texte fondateur de cette période : il organise un contrat de travail spécifique aux travailleurs africains, fondé sur une logique d'encadrement et de discipline de la main-d'œuvre plus que de protection. Ce régime est resté la base du contrat de travail des Africains jusqu'à la fin de la colonisation, amélioré par l'arrêté royal du 19 juillet 1954 puis par le décret du 10 juin 1958. Parallèlement, l'hygiène et la sécurité du travail ont fait l'objet d'une réglementation propre dès le décret du 21 mars 1950, complété par les ordonnances du 6 mai 1953 et du 6 avril 1954." },
      { type: 'paragraphe', texte: "L'indépendance du 30 juin 1960 n'a pas immédiatement produit un code unifié. La législation du travail est restée éparse et dense pendant sept ans, jusqu'à la promulgation du premier Code du travail congolais par l'ordonnance-loi n°67-310 du 9 août 1967. Ce texte a unifié le régime du contrat de travail, mis fin à la distinction coloniale entre travailleurs selon leur origine et organisé les institutions qui structurent encore la matière : inspection du travail, organisations professionnelles, conventions collectives, tribunaux du travail. Il a régi les relations de travail pendant trente-cinq ans, sous les régimes politiques successifs de la Deuxième République et de la transition, ce qui explique que le Code de 2002 y renvoie encore explicitement dans ses dispositions transitoires." },
      { type: 'filet', titre: "Article 331 du Code du travail", texte: "« Les organisations professionnelles d'employeurs et de travailleurs, agréées par application du Code du Travail annexé à l'ordonnance-loi n° 67-310 du 9 août 1967 seront enregistrées d'office par le Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions. Toutefois, ces organisations auront à conformer leurs statuts aux dispositions révisées du présent Code dans un délai maximum de six mois à compter de son entrée en vigueur. »" },
      { type: 'paragraphe', texte: "La loi n°015/2002 du 16 octobre 2002 a abrogé et remplacé ce premier code. Son article 332 le dit sans détour : « Le présent Code abroge et remplace toutes dispositions législatives antérieurement en vigueur en matière du travail. Les institutions, procédures et les mesures réglementaires existant en application de la législation et de la réglementation en matière du travail non-contraires aux dispositions du présent Code restent en vigueur. » Cette seconde phrase est importante en pratique : un arrêté ministériel pris sous l'empire du code de 1967 continue de s'appliquer tant qu'il n'est pas contraire au Code de 2002 et tant qu'il n'a pas été remplacé. Le juriste ne peut donc pas écarter un texte réglementaire au seul motif de son ancienneté." },
      { type: 'paragraphe', texte: "Le Code de 2002 a été adopté dans un contexte précis : celui de la sortie de guerre et de la mise à niveau du droit congolais par rapport aux normes internationales du travail. En juin 2001, à l'issue de la 89e session de la Conférence internationale du Travail, la ministre du Travail et de la Prévoyance sociale avait déposé auprès du Bureau international du Travail les instruments de ratification de sept conventions, dont la convention n°87 sur la liberté syndicale et la protection du droit syndical (1948) et la convention n°182 sur les pires formes de travail des enfants (1999). La RDC rejoignait ainsi le groupe, alors d'une cinquantaine d'États, ayant ratifié les huit conventions fondamentales de l'Organisation internationale du Travail. Le Code de 2002 traduit ces engagements en droit interne : c'est de là que viennent l'article 3 sur les pires formes de travail des enfants, dont la rédaction reprend presque mot pour mot l'article 3 de la convention n°182, et le relèvement de l'âge minimum de l'article 6." },
      { type: 'paragraphe', texte: "Le Code prévoyait lui-même sa propre mise en œuvre réglementaire. L'article 333 impose que « les décrets du Président de la République et les arrêtés du Ministre ayant le Travail et la Prévoyance Sociale dans ses attributions, prévus par le présent Code, devront être pris dans le délai maximum d'un an à partir de sa publication au “Journal Officiel” ». Ce délai n'a pas été respecté pour tous les textes, et certains arrêtés d'application, notamment sur les travaux légers autorisés aux mineurs, ont été pris avec retard ou attendent encore. L'article 330, pour sa part, règle le sort des contrats en cours : les dispositions du Code leur sont « de plein droit applicables aux contrats individuels en cours sous réserve que les travailleurs continuent à bénéficier des avantages qui leur ont été consentis antérieurement lorsque ceux-ci sont supérieurs à ceux que leur reconnaît le présent Code ». On reconnaît là le principe de faveur, appliqué cette fois à la succession des lois dans le temps : la loi nouvelle s'applique immédiatement, mais elle ne peut retirer un avantage acquis." },
      { type: 'paragraphe', texte: "La loi n°16/010 du 15 juillet 2016 a ensuite modifié et complété le Code sans le refondre. Son exposé des motifs justifie l'intervention par l'inadaptation de certaines dispositions de 2002 à l'évolution socio-économique et aux normes internationales du travail. Elle a modifié quinze articles : 1, 6, 7, 62, 119, 121, 125, 129, 190, 216, 217, 218, 219, 241 et 321. Trois innovations dominent. La première concerne les femmes : la loi de 2016 ouvre le travail de nuit aux femmes, jusque-là interdit par principe, et protège la travailleuse enceinte en lui permettant de suspendre son contrat sans que cette suspension puisse constituer un motif de résiliation. La deuxième concerne l'article 1er, dont le champ d'application est réécrit pour viser expressément les entreprises publiques et les travailleurs des services publics engagés par contrat. La troisième concerne l'article 6 sur la capacité, dont la procédure de dérogation pour les mineurs de quinze ans est précisée. Le même jour, la loi n°16/008 modifiant le Code de la famille a réformé le régime de l'autorisation maritale, ce qui a levé un obstacle juridique à la conclusion d'un contrat de travail par la femme mariée : la capacité de la travailleuse ne dépend plus de l'accord de son conjoint." },
      { type: 'tableau', tableau: { entetes: ['Date', 'Texte', 'Apport'], lignes: [
        ['16 mars 1922', "Décret relatif au contrat de travail entre maîtres civilisés et indigènes", "Premier régime spécifique du travail salarié africain ; logique d'encadrement de la main-d'œuvre"],
        ['1950-1954', "Décret du 21 mars 1950, ordonnances du 6 mai 1953 et du 6 avril 1954", "Naissance d'une réglementation de l'hygiène et de la sécurité du travail"],
        ['19 juillet 1954 et 10 juin 1958', "Arrêté royal, puis décret", "Amélioration du régime du contrat de travail des Africains, sans abandonner la base de 1922"],
        ['9 août 1967', "Ordonnance-loi n°67-310 portant Code du travail", "Premier code unifié de l'État indépendant ; institutions toujours en place"],
        ['20 juin 2001', "Dépôt de sept instruments de ratification de conventions OIT (89e session CIT)", "La RDC ratifie l'ensemble des huit conventions fondamentales"],
        ['16 octobre 2002', "Loi n°015/2002 portant Code du travail", "Code actuel : 16 titres, 334 articles ; abroge le code de 1967 (art. 332)"],
        ['15 juillet 2016', "Loi n°16/010 modifiant et complétant le Code", "15 articles modifiés : travail de nuit des femmes, grossesse, champ d'application, capacité"],
        ['30 mai 2025', "Décret n°25/22 (SMIG, allocations familiales minima, contre-valeur du logement)", "Premier relèvement du SMIG depuis 2018, en deux paliers (mai 2025, janvier 2026)"],
      ] } },
      { type: 'paragraphe', texte: "Cette chronologie n'est pas close. Depuis 2025, plusieurs initiatives parlementaires visent à modifier de nouveau le Code : une proposition de loi déposée le 28 mai 2025 par le député Éric Tshikuma Mwimbayi, qui entend aligner le Code sur la Constitution de 2006 (voir la section 1.10), et une proposition déposée le 15 mai 2026 par le député Prince Kangila Kawele sur le travail domestique (voir la section 1.4). Ni l'une ni l'autre n'est, à la date de rédaction de ce chapitre, une loi en vigueur. L'étudiant doit savoir distinguer trois états d'un texte : le droit positif applicable (le Code de 2002 révisé en 2016 et ses textes d'application), le droit en projet (les propositions déposées) et le droit abrogé (le code de 1967), dont la connaissance reste utile pour lire les décisions et les conventions collectives anciennes." },
    ],
  },
  {
    numero: '1.3',
    titre: "Les sources du droit du travail et leur hiérarchie",
    navLabel: '1.3 Sources et hiérarchie',
    blocs: [
      { type: 'paragraphe', texte: "Le droit du travail congolais se déploie à plusieurs niveaux hiérarchisés, chacun ne pouvant que préciser ou améliorer le niveau supérieur, jamais le contredire en défaveur du travailleur. Au sommet se trouve la Constitution du 18 février 2006, telle que révisée en 2011. Elle ne se contente pas de renvoyer à la loi : elle pose elle-même les principes fondamentaux de la matière, qui s'imposent au législateur et peuvent être invoqués devant la Cour constitutionnelle." },
      { type: 'filet', titre: "Article 36 de la Constitution", texte: "« Le travail est un droit et un devoir sacrés pour chaque Congolais. L'État garantit le droit au travail, la protection contre le chômage et une rémunération équitable et satisfaisante assurant au travailleur ainsi qu'à sa famille une existence conforme à la dignité humaine, complétée par tous les autres moyens de protection sociale, notamment la pension de retraite et la rente viagère. Nul ne peut être lésé dans son travail en raison de ses origines, de son sexe, de ses opinions, de ses croyances ou de ses conditions socio-économiques. Tout Congolais a le droit et le devoir de contribuer par son travail à la construction et à la prospérité nationales. La loi établit le statut des travailleurs et réglemente les particularités propres au régime juridique des ordres professionnels et l'exercice des professions exigeant une qualification scolaire ou académique. »" },
      { type: 'paragraphe', texte: "Trois autres dispositions constitutionnelles complètent ce socle. L'article 38 dispose que « la liberté syndicale est reconnue et garantie » et que « tous les Congolais ont le droit de fonder des syndicats ou de s'y affilier librement, dans les conditions fixées par la loi ». L'article 39 reconnaît et garantit le droit de grève, qui « s'exerce dans les conditions fixées par la Loi qui peut en interdire ou en limiter l'exercice dans les domaines de la défense nationale et de la sécurité ou pour toute activité ou tout service public d'intérêt vital pour la nation ». L'article 37 garantit plus généralement la liberté d'association. Ces textes fondent le Titre XII du Code sur les relations professionnelles (chapitre 8) et le Titre XIII sur les conflits collectifs (chapitre 9). Enfin, l'article 122 réserve à la loi, en son point 14, « le droit du travail et de la sécurité sociale » : un décret ou un arrêté ne peut donc créer une règle de fond en la matière que sur habilitation de la loi, et dans les limites de cette habilitation. Cette réserve de compétence est au cœur de la critique constitutionnelle formulée en 2025 contre le Code, étudiée à la section 1.10." },
      { type: 'paragraphe', texte: "Au deuxième niveau figurent les traités internationaux. L'article 215 de la Constitution dispose que « les traités et accords internationaux régulièrement conclus ont, dès leur publication, une autorité supérieure à celle des lois, sous réserve pour chaque traité ou accord, de son application par l'autre partie ». Les conventions de l'Organisation internationale du Travail ratifiées par la RDC s'intègrent donc à l'ordre juridique interne avec une valeur supérieure à celle du Code du travail lui-même. Selon les données de la base NORMLEX de l'OIT, la RDC a ratifié trente-sept conventions, dont trente-trois sont en vigueur : les huit conventions fondamentales, deux des quatre conventions dites de gouvernance et vingt-sept conventions techniques. Les huit fondamentales couvrent la liberté syndicale et la négociation collective (conventions n°87 et n°98), l'abolition du travail forcé (n°29 et n°105), l'égalité de rémunération et la non-discrimination (n°100 et n°111) et le travail des enfants (n°138 sur l'âge minimum et n°182 sur les pires formes)." },
      { type: 'tableau', tableau: { entetes: ['Convention OIT', 'Objet', 'Trace dans le Code du travail'], lignes: [
        ['n°29 (1930) et n°105 (1957)', "Interdiction du travail forcé ou obligatoire", "Art. 2, al. 2 et 3"],
        ['n°87 (1948) et n°98 (1949)', "Liberté syndicale, droit d'organisation et de négociation collective", "Titre XII, art. 230 à 296"],
        ['n°100 (1951) et n°111 (1958)', "Égalité de rémunération ; non-discrimination dans l'emploi", "Art. 1er (critères d'indifférence), art. 86"],
        ['n°138 (1973) et n°182 (1999)', "Âge minimum d'admission à l'emploi ; pires formes de travail des enfants", "Art. 3 à 6"],
        ['n°190 (2019)', "Violence et harcèlement dans le monde du travail", "Non ratifiée ; projet de loi de ratification déposé au Sénat le 7 avril 2025"],
      ] } },
      { type: 'paragraphe', texte: "La hiérarchie ainsi construite reste vivante : elle continue d'évoluer au gré des ratifications. La convention n°190 de l'OIT sur l'élimination de la violence et du harcèlement dans le monde du travail, entrée en vigueur le 25 juin 2021, n'est pas ratifiée par la RDC à la date de rédaction de ce chapitre. Un projet de loi autorisant sa ratification a été déposé au Sénat le 7 avril 2025 par le sénateur Cédric Ngindu, et des organisations syndicales et de la société civile en plaident l'adoption. Cet exemple illustre une règle de méthode : une norme internationale peut exister et lier d'autres États sans produire d'effet en droit congolais tant que l'acte de ratification n'est pas intervenu et publié. Un plaideur ne peut donc pas invoquer la convention n°190 devant un tribunal du travail congolais ; il peut, en revanche, invoquer les conventions n°111 ou n°87, ratifiées, y compris contre une disposition législative contraire." },
      { type: 'paragraphe', texte: "Au troisième niveau vient la loi : le Code du travail, mais aussi les lois qui interfèrent avec lui, comme la loi n°09/001 du 10 janvier 2009 portant protection de l'enfant, la loi n°16/009 du 15 juillet 2016 sur le régime général de la sécurité sociale, ou le Code de la famille auquel l'article 7 renvoie pour la définition des enfants. Au quatrième niveau se trouvent les textes réglementaires d'application : décrets du Premier ministre et arrêtés du ministre ayant le Travail dans ses attributions. Leur importance pratique est considérable, car c'est par eux que sont fixés le salaire minimum interprofessionnel garanti, la liste des jours fériés légaux, la liste des travaux légers autorisés aux mineurs, l'organisation des comités de sécurité ou le fonctionnement du Comité national de lutte contre les pires formes de travail des enfants. Le décret n°25/22 du 30 mai 2025 portant fixation du SMIG, des allocations familiales minima et de la contre-valeur du logement en est l'exemple le plus récent et le plus commenté." },
      { type: 'paragraphe', texte: "Au cinquième niveau se situent les sources conventionnelles, c'est-à-dire négociées entre partenaires sociaux : les conventions collectives d'entreprise, de branche ou interprofessionnelles, régies par le Titre XII du Code. Elles ne peuvent déroger aux dispositions d'ordre public de la loi, mais peuvent être plus favorables, et elles le sont souvent : c'est dans les conventions collectives que l'on trouve les grilles de classification, les primes d'ancienneté, les indemnités de logement ou de transport supérieures aux minima légaux. Au sixième niveau, enfin, viennent les sources propres à l'entreprise et au contrat : le règlement d'entreprise, établi par l'employeur sous le contrôle de l'inspection du travail, et le contrat individuel de travail. À tous ces niveaux s'ajoutent les usages professionnels, qui peuvent créer des droits lorsqu'ils sont constants, généraux et fixes, et que le juge du travail retient comme éléments de preuve des conditions de travail effectives." },
      { type: 'tableau', tableau: { entetes: ['Niveau', 'Source', 'Exemple'], lignes: [
        ['1. Constitutionnel', "Constitution du 18 février 2006", "Art. 36 (droit au travail), 38 (liberté syndicale), 39 (grève), 122 point 14 (réserve de loi)"],
        ['2. International', "Conventions OIT ratifiées (art. 215 : autorité supérieure à la loi)", "37 conventions ratifiées, 33 en vigueur, dont les 8 fondamentales"],
        ['3. Législatif', "Loi n°015/2002, mod. loi n°16/010 ; lois connexes", "Code du travail, art. 1 à 334 ; loi n°09/001 (enfant) ; loi n°16/009 (sécurité sociale)"],
        ['4. Réglementaire', "Décrets et arrêtés d'exécution", "Décret n°25/22 du 30 mai 2025 (SMIG) ; arrêté n°075 du 9 octobre 2025 (visa ONEM des offres d'emploi)"],
        ['5. Conventionnel', "Conventions et accords collectifs (Titre XII)", "Convention collective d'entreprise ou de branche"],
        ['6. Entreprise et contrat', "Règlement d'entreprise, contrat individuel, usages", "CDD, CDI, clause d'essai, prime d'usage"],
      ] } },
      { type: 'paragraphe', texte: "La jurisprudence et la doctrine complètent ce tableau sans être des sources de droit au sens strict. Les décisions des tribunaux du travail, des cours d'appel et de la Cour de cassation, dont le siège est à Gombe, n'ont pas d'autorité normative générale, mais elles fixent l'interprétation des textes et guident la pratique. Leur accessibilité reste limitée : il n'existe pas de recueil systématique de jurisprudence sociale congolaise, ce qui explique le rôle accru de la doctrine. L'ouvrage collectif dirigé par Loko Mantuono, Droit social, droit du travail et de la sécurité sociale en RDC, publié chez L'Harmattan en 2022, en offre une synthèse récente qui reprend et actualise cette architecture des sources ; les Codes Larcier de la RDC, dont le tome IV est consacré au droit du travail et de la sécurité sociale, rassemblent les textes réglementaires d'application." },
      { type: 'controle', question: {
        id: 'ctrl-1-3', question: "Un arrêté ministériel fixe un avantage inférieur à celui prévu par une convention OIT ratifiée par la RDC. Quelle norme le tribunal du travail doit-il appliquer ?",
        options: [
          { id: 'a', texte: "L'arrêté, parce qu'il est plus récent et plus précis" },
          { id: 'b', texte: "La convention OIT, parce qu'un traité régulièrement ratifié et publié a une autorité supérieure à la loi et, a fortiori, au règlement (Constitution, art. 215)" },
          { id: 'c', texte: "Ni l'un ni l'autre : le tribunal doit surseoir à statuer et saisir la Cour constitutionnelle" },
          { id: 'd', texte: "L'arrêté, parce que les conventions OIT ne s'appliquent qu'aux États et non aux employeurs privés" },
          { id: 'e', texte: "La convention OIT, mais seulement si elle a été reprise mot pour mot dans le Code du travail" },
        ],
        reponseCorrecte: 'b', articleRef: "Constitution, art. 215",
        explication: "L'article 215 de la Constitution donne aux traités et accords régulièrement conclus, dès leur publication, une autorité supérieure à celle des lois, sous réserve de réciprocité. Un arrêté, norme réglementaire inférieure à la loi, ne peut prévaloir sur une convention ratifiée. La reprise dans le Code n'est pas une condition d'applicabilité.",
      } },
    ],
  },
  {
    numero: '1.4',
    titre: "Le champ d'application du Code du travail (article 1er)",
    navLabel: "1.4 Champ d'application",
    blocs: [
      { type: 'paragraphe', texte: "Le champ d'application du Code est défini par son article 1er, réécrit par la loi n°16/010 de 2016. Sa lecture attentive est indispensable : c'est lui qui décide si une relation donnée relève du Code du travail, d'un statut de droit public ou d'un régime particulier, et donc si les règles étudiées dans ce manuel (préavis, licenciement, congés, décompte final) s'appliquent. Le texte procède en trois temps : un principe d'application générale, une règle spéciale pour les gens de mer et de navigation intérieure, et une liste limitative d'exclusions." },
      { type: 'carte', titre: "Article 1er, alinéas 1 et 2 (modifié par la loi n°16/010 du 15 juillet 2016)", note: "« Le présent code est applicable à tous les travailleurs et à tous les employeurs, y compris ceux des entreprises publiques exerçant leur activité professionnelle sur l'étendue de la République Démocratique du Congo, quels que soient la race, le sexe, l'état civil, la religion, l'opinion politique, l'ascendance nationale, l'origine sociale, la nationalité des parties, la nature des prestations, la rémunération ou le lieu de conclusion du contrat, dès lors que ce dernier s'exécute en République Démocratique du Congo. Il s'applique également aux travailleurs des services publics de l'État engagés par le contrat de travail. Il ne s'applique aux marins et bateliers de navigation intérieure qu'en cas de silence des règlements particuliers qui les concernent ou lorsque ces règlements et ceux régis par les statuts particuliers s'y réfèrent expressément. »" },
      { type: 'paragraphe', texte: "Le principe est celui d'une application universelle et territoriale. Universelle, parce que le texte énumère une série de critères d'indifférence : la race, le sexe, l'état civil, la religion, l'opinion politique, l'ascendance nationale, l'origine sociale et la nationalité des parties ne changent rien à l'applicabilité du Code. Cette liste fait écho à l'article 13 de la Constitution, qui interdit toute mesure discriminatoire fondée sur la religion, l'origine familiale, la condition sociale, la résidence, les opinions politiques, l'appartenance à une race, une ethnie, une tribu ou une minorité culturelle ou linguistique, et à la convention n°111 de l'OIT sur la discrimination dans l'emploi. Elle produit une conséquence pratique immédiate : un travailleur étranger employé à Kinshasa par une société étrangère relève du Code du travail congolais, quelle que soit la loi choisie dans son contrat. Territoriale, parce que le critère décisif est le lieu d'exécution du contrat, « dès lors que ce dernier s'exécute en République Démocratique du Congo ». Le lieu de conclusion est indifférent : un contrat signé à Bruxelles ou à Johannesburg pour un emploi à Lubumbashi est soumis au Code." },
      { type: 'paragraphe', texte: "Deux précisions de 2016 méritent l'attention. La première inclut expressément « ceux des entreprises publiques », c'est-à-dire les travailleurs et employeurs des entreprises du portefeuille de l'État transformées en sociétés commerciales ou maintenues sous forme d'établissements publics à caractère industriel et commercial : leurs agents, engagés par contrat, sont des travailleurs au sens du Code, et non des fonctionnaires. La seconde vise « les travailleurs des services publics de l'État engagés par le contrat de travail ». Un ministère ou une administration peut recruter du personnel sous contrat de travail (chauffeurs, agents d'entretien, consultants salariés), en dehors du statut de la fonction publique ; ces personnes relèvent du Code, avec toutes les conséquences en matière de préavis et d'indemnités, alors que leurs collègues sous statut relèvent de la loi n°16/013 du 15 juillet 2016 portant statut des agents de carrière des services publics de l'État." },
      { type: 'paragraphe', texte: "Le deuxième alinéa réserve le cas des marins et des bateliers de navigation intérieure, catégorie importante dans un pays traversé par le fleuve Congo et ses affluents, ainsi que par les Grands Lacs. Le Code ne leur est applicable « qu'en cas de silence des règlements particuliers qui les concernent ou lorsque ces règlements et ceux régis par les statuts particuliers s'y réfèrent expressément ». Le Code joue donc à leur égard un rôle subsidiaire : il comble les lacunes de la réglementation maritime et fluviale, sans s'y substituer." },
      { type: 'carte', titre: "Article 1er, alinéa 3 : les exclusions", note: "« Sont exclus du champ d'application de la présente loi : les magistrats, les juges consulaires des Tribunaux de commerce et les juges assesseurs des Tribunaux du travail ; les agents de carrière des Services publics de l'État régis par le statut général ; les agents et fonctionnaires de carrière des Services publics de l'État régis par des statuts particuliers ; les éléments des Forces armées de la République Démocratique du Congo, de la Police nationale congolaise et du Service national. »" },
      { type: 'paragraphe', texte: "Ces exclusions ne signifient pas une absence de protection : les catégories concernées relèvent d'un statut légal ou réglementaire propre plutôt que du régime organisé par le Code. Un magistrat ou un fonctionnaire de carrière ne peut donc jamais se prévaloir des règles de préavis, de licenciement ou de décompte final étudiées dans ce manuel. Il relève d'un contentieux et d'une procédure disciplinaire distincts. Chacune des quatre exclusions répond à une même logique : celle de statuts déjà pourvus d'un régime disciplinaire et contentieux propre, dont la superposition avec le Code créerait un conflit de compétence. Le magistrat relève du statut de la magistrature et de l'autorité du Conseil supérieur de la magistrature ; l'agent de carrière relève de la loi n°16/013 ; les agents régis par des statuts particuliers (personnel de l'enseignement supérieur et universitaire, par exemple) relèvent de leur statut ; le militaire, le policier ou le membre du Service national relève de la justice militaire et de textes propres. Le juge consulaire du tribunal de commerce et le juge assesseur du tribunal du travail, quant à eux, ne sont pas des salariés du tribunal auprès duquel ils siègent : ils exercent une fonction juridictionnelle, étrangère par nature au salariat." },
      { type: 'tableau', tableau: { entetes: ['Situation', 'Relève du Code du travail ?', 'Fondement'], lignes: [
        ["Comptable engagé par contrat par une société privée de Kinshasa", "Oui", "Art. 1er, al. 1 : principe général"],
        ["Ingénieur de nationalité indienne employé à Kolwezi par une société minière", "Oui", "Art. 1er : indifférence de la nationalité ; contrat exécuté en RDC"],
        ["Agent de la SNEL ou de la Gécamines engagé par contrat", "Oui", "Art. 1er : « y compris ceux des entreprises publiques »"],
        ["Chauffeur engagé par contrat de travail par un ministère", "Oui", "Art. 1er : travailleurs des services publics engagés par contrat"],
        ["Inspecteur des finances, agent de carrière sous statut général", "Non", "Art. 1er, al. 3 : statut général (loi n°16/013)"],
        ["Professeur d'université sous statut particulier", "Non", "Art. 1er, al. 3 : statut particulier"],
        ["Magistrat, juge consulaire, juge assesseur", "Non", "Art. 1er, al. 3"],
        ["Militaire des FARDC, policier de la PNC", "Non", "Art. 1er, al. 3"],
        ["Matelot d'une compagnie fluviale", "Subsidiairement", "Art. 1er, al. 2 : en cas de silence des règlements particuliers"],
        ["Employée de maison chez un particulier", "Oui", "Aucune exclusion ne la vise ; voir le débat ci-dessous"],
      ] } },
      { type: 'paragraphe', texte: "Le champ d'application ainsi délimité n'est pas figé. Il fait aujourd'hui l'objet d'un débat qui dépasse le strict commentaire de l'article 1er : celui de la place des travailleurs domestiques, chauffeurs particuliers, cuisiniers, gardiens et femmes de ménage employés par des particuliers. Ces travailleurs ne figurent pas parmi les catégories exclues et relèvent donc, en droit positif, du Code du travail commun : ils ont droit au SMIG, aux congés, au préavis et à l'affiliation à la CNSS. La pratique révèle cependant une protection largement théorique, faute de contrat écrit, d'affiliation et de contrôle de l'inspection du travail dans la sphère domestique. C'est dans ce contexte qu'une proposition de loi modifiant le Code du travail a été déposée à l'Assemblée nationale le 15 mai 2026 par le député Prince Kangila Kawele, afin d'instituer un régime légal spécifique au personnel domestique : contrat écrit, salaire minimum, cotisations sociales, accès aux soins de santé et conditions de travail. Le syndicat LA CLÉ a aussitôt jugé l'initiative inopportune, faisant valoir que les domestiques sont déjà couverts par l'article 1er et que le problème tient non à l'absence de droits mais à leur violation systématique. Ce débat est un excellent exercice de qualification : la question n'est pas de savoir si ces travailleurs ont des droits, ils en ont, mais si un régime spécial en améliorerait l'effectivité. Il s'agit à ce stade d'une initiative législative, non d'un texte en vigueur : elle doit être présentée comme telle, sans être confondue avec le droit positif applicable aujourd'hui." },
    ],
  },
  {
    numero: '1.5',
    titre: "Le droit au travail et l'interdiction du travail forcé (article 2)",
    navLabel: '1.5 Droit au travail',
    blocs: [
      { type: 'paragraphe', texte: "Le chapitre II du Titre I est consacré au droit au travail. Il ne compte qu'un article, mais cet article condense deux idées de portée constitutionnelle et internationale : le travail comme droit et devoir, et l'interdiction absolue du travail forcé." },
      { type: 'filet', titre: "Article 2 du Code du travail", texte: "« Le travail est pour chacun un droit et un devoir. Il constitue une obligation morale pour tous ceux qui n'en sont pas empêchés par l'âge ou l'inaptitude au travail constatée par un médecin. Le travail forcé ou obligatoire est interdit. Tombe également sous le coup de l'interdiction, tout travail ou service exigé d'un individu sous menace d'une peine quelconque et pour lequel ledit individu ne s'est pas offert de plein gré. »" },
      { type: 'paragraphe', texte: "Le premier alinéa reprend, en l'adaptant, la formule de l'article 36 de la Constitution selon laquelle le travail est « un droit et un devoir sacrés pour chaque Congolais ». Le droit au travail n'est pas un droit subjectif à obtenir un emploi déterminé, opposable à un employeur ou à l'État devant un tribunal : aucun juge ne peut condamner une entreprise à embaucher. C'est un droit-créance de nature programmatique, qui oblige l'État à mener des politiques de l'emploi, à protéger contre le chômage et à organiser le placement des demandeurs d'emploi. C'est le fondement de l'Office national de l'emploi (ONEM), étudié au chapitre 8, dont la mission est précisément de rapprocher l'offre et la demande de travail. Le devoir de travailler, quant à lui, est qualifié par le Code d'« obligation morale » : il n'est assorti d'aucune sanction juridique et connaît deux limites expresses, l'âge et l'inaptitude constatée par un médecin. Cette qualification morale est essentielle, car elle empêche que le devoir de travailler serve de prétexte à un travail imposé, ce que le deuxième alinéa interdit précisément." },
      { type: 'paragraphe', texte: "Le deuxième et le troisième alinéa posent l'interdiction du travail forcé ou obligatoire. La définition retenue est celle de l'article 2 de la convention n°29 de l'OIT de 1930 : est forcé « tout travail ou service exigé d'un individu sous menace d'une peine quelconque et pour lequel ledit individu ne s'est pas offert de plein gré ». Deux éléments doivent être réunis : l'absence de consentement libre (« ne s'est pas offert de plein gré ») et la contrainte (« sous menace d'une peine quelconque »). La peine s'entend largement : elle n'est pas seulement pénale, elle peut être une sanction économique, la rétention de documents d'identité, la privation de salaire ou la menace de dénonciation. Cette interdiction relève de l'ordre public absolu : le consentement donné sous contrainte ne vaut rien, et un contrat de travail qui organiserait une telle situation serait nul en son entier." },
      { type: 'paragraphe', texte: "L'interdiction rejoint deux conventions fondamentales ratifiées par la RDC, la convention n°29 et la convention n°105 de 1957 sur l'abolition du travail forcé, qui interdit notamment le travail forcé comme mesure de coercition politique, de discipline du travail ou de discrimination. Le protocole de 2014 relatif à la convention n°29, adopté à Genève le 11 juin 2014 pour renforcer la prévention du travail forcé et la protection des victimes, en particulier contre la traite des personnes, fait l'objet d'appels à la ratification universelle ; son statut de ratification par la RDC n'a pas pu être vérifié à partir d'une source officielle lors de la rédaction de ce chapitre, et l'étudiant est invité à le contrôler dans la base NORMLEX avant toute affirmation. En droit interne, les formes contemporaines du travail forcé (servitude pour dettes, travail sous contrainte dans les sites miniers artisanaux, exploitation domestique) relèvent aussi du droit pénal et, s'agissant des enfants, de l'article 3 du Code, étudié à la section suivante." },
      { type: 'carte', titre: "Ce que l'article 2 n'interdit pas", texte: "La convention n°29 exclut de la notion de travail forcé le service militaire obligatoire pour des travaux de caractère purement militaire, les obligations civiques normales, le travail pénitentiaire exécuté sous le contrôle des autorités publiques, les travaux exigés en cas de force majeure (guerre, sinistre, épidémie) et les menus travaux de village exécutés dans l'intérêt direct de la collectivité. Le Code du travail ne reprend pas cette liste ; elle s'applique néanmoins en RDC par l'effet de la ratification et de l'article 215 de la Constitution. Les corvées collectives imposées par une autorité locale sous menace d'amende sortent de ces exceptions dès qu'elles dépassent les menus travaux d'intérêt communautaire consultés avec la population." },
      { type: 'paragraphe', texte: "Sur le plan de la sanction, le travail forcé constitue une infraction pénale au sens du Titre XV du Code (chapitre 9), qui punit l'exigence d'un travail forcé ou obligatoire. Il ouvre en outre droit, pour la victime, à la réparation du préjudice subi et à la rémunération du travail effectivement fourni, le Code ne permettant pas à l'auteur de l'infraction de s'enrichir du travail extorqué." },
    ],
  },
  {
    numero: '1.6',
    titre: "L'abolition des pires formes de travail des enfants (articles 3 à 5)",
    navLabel: "1.6 Travail des enfants",
    blocs: [
      { type: 'paragraphe', texte: "Les articles 3 à 5 du Code transposent en droit interne la convention n°182 de l'OIT, ratifiée par la RDC en 2001. Ils ne visent pas tout travail des enfants, question réglée par l'article 6 sur la capacité, mais ses pires formes, dont l'abolition est immédiate et sans exception." },
      { type: 'carte', titre: "Article 3 du Code du travail", note: "« Toutes les pires formes de travail des enfants sont abolies. L'expression “les pires formes de travail des enfants” comprend notamment : a) toutes les formes d'esclavage ou pratiques analogues, telles que la vente et la traite des enfants, la servitude pour dettes et le servage ainsi que le travail forcé ou obligatoire, y compris le recrutement forcé ou obligatoire des enfants en vue de leur utilisation dans des conflits armés ; b) l'utilisation, le recrutement ou l'offre d'un enfant à des fins de prostitution, de production de matériel pornographique de spectacles pornographiques ou des danses obscènes ; c) l'utilisation, le recrutement ou l'offre d'un enfant aux fins d'activités illicites, notamment pour la production et le trafic de stupéfiants ; d) les travaux qui, par leur nature ou les conditions dans lesquelles ils s'exercent, sont susceptibles de nuire à la santé, à la sécurité, à la dignité ou à la moralité de l'enfant. »" },
      { type: 'paragraphe', texte: "La liste est introduite par « notamment » : elle n'est pas limitative, et l'autorité peut y ajouter d'autres formes. Les trois premières catégories (esclavage et pratiques analogues, exploitation sexuelle, activités illicites) sont des infractions en elles-mêmes, quel que soit l'âge de la victime ; leur mention dans le Code du travail rappelle qu'elles ne peuvent jamais être qualifiées de « travail ». La quatrième catégorie, les travaux dangereux, est la plus importante pour le droit du travail, car elle concerne des activités licites en soi (extraction minière, transport de charges, travail de nuit, manipulation de produits chimiques) qui deviennent interdites lorsqu'elles sont confiées à un enfant. La loi n°09/001 du 10 janvier 2009 portant protection de l'enfant complète ce dispositif : elle définit l'enfant comme toute personne âgée de moins de dix-huit ans et prohibe l'engagement d'un enfant de moins de quinze ans, en réservant les travaux légers aux plus de seize ans selon les conditions que le chapitre suivant précise." },
      { type: 'paragraphe', texte: "Les articles 4 et 5 créent l'organe chargé de la mise en œuvre. L'article 4 institue « un Comité National de lutte contre les pires formes de travail des enfants », dont la mission est « d'élaborer la stratégie nationale en vue de l'éradication des pires formes de travail des enfants » et « d'assurer le suivi de la mise en œuvre de la stratégie et d'évaluer le niveau d'application des mesures préconisées ». L'article 5 renvoie à « un arrêté interministériel, pris par les Ministres ayant dans leurs attributions respectivement le Travail et la Prévoyance Sociale et les Affaires Sociales et Famille », pour déterminer son organisation et son fonctionnement. Ce choix d'un organe interministériel traduit la nature transversale du problème : le travail des enfants relève du travail, mais aussi des affaires sociales, de l'éducation, des mines et de la justice." },
      { type: 'paragraphe', texte: "La réalité congolaise donne à ces textes une acuité particulière. Le secteur minier artisanal du cuivre et du cobalt, dans les provinces du Lualaba et du Haut-Katanga, est le terrain le plus documenté. Les estimations varient fortement selon les sources et les méthodes : des organisations internationales avancent le chiffre d'environ quarante mille enfants impliqués dans l'extraction artisanale du cobalt, tandis que la Commission nationale des droits de l'homme, dans le rapport d'enquête qu'elle a publié en février 2025, recense 16 845 enfants, filles et garçons, sur les sites artisanaux de cobalt pour la période 2019-2022, et relève une baisse significative du phénomène. Les deux chiffres ne mesurent pas la même chose (estimation globale d'un côté, recensement sur sites identifiés de l'autre) et doivent être cités avec leur méthode. Des programmes publics, comme le Projet d'appui au bien-être alternatif des enfants et jeunes impliqués dans la chaîne d'approvisionnement du cobalt (PABEA-Cobalt), et une feuille de route nationale de lutte contre le travail des enfants, révisée en 2024 dans le cadre de l'Alliance 8.7, structurent l'action publique. Ces éléments relèvent de la politique de l'emploi ; ils ne modifient pas la règle de droit, mais éclairent la distance entre la norme et son effectivité." },
      { type: 'tableau', tableau: { entetes: ["Catégorie de l'art. 3", 'Exemples', 'Régime'], lignes: [
        ["a) Esclavage et pratiques analogues", "Traite, servitude pour dettes, recrutement d'enfants soldats", "Interdiction absolue ; infractions pénales autonomes"],
        ["b) Exploitation sexuelle", "Prostitution, pornographie, danses obscènes", "Interdiction absolue ; loi n°09/001 et droit pénal"],
        ["c) Activités illicites", "Production et trafic de stupéfiants", "Interdiction absolue"],
        ["d) Travaux dangereux", "Mines artisanales, transport de charges lourdes, travail de nuit, produits toxiques", "Interdits aux moins de 18 ans ; liste des travaux légers autorisés par arrêté (art. 6)"],
      ] } },
      { type: 'paragraphe', texte: "Ces dispositions se combinent avec l'article 6 sur la capacité de contracter, étudié à la section suivante : là où l'article 3 interdit certaines formes de travail quel que soit le consentement, l'article 6 organise les conditions dans lesquelles un mineur peut, exceptionnellement, être engagé pour un travail licite et adapté à son âge. La difficulté, largement documentée par la doctrine et les organisations internationales, tient moins à l'existence de la règle qu'à son application effective dans le secteur informel, où l'essentiel du travail des enfants échappe structurellement au contrôle de l'inspection du travail. Ce constat ne retire rien à la valeur normative des articles 3 à 6 : il invite à distinguer, dans l'analyse d'un cas, la règle de droit applicable de son effectivité pratique, deux questions qu'un juriste doit savoir traiter séparément." },
    ],
  },
  {
    numero: '1.7',
    titre: "La capacité de contracter (article 6)",
    navLabel: '1.7 Capacité de contracter',
    blocs: [
      { type: 'paragraphe', texte: "Le chapitre III du Titre I règle la capacité de conclure un contrat de travail. L'article 6, réécrit en 2016, pose d'abord une règle de conflit de lois, puis fixe l'âge de la capacité et organise deux régimes dérogatoires pour les mineurs." },
      { type: 'carte', titre: "Article 6, alinéas 1 et 2 (modifié par la loi n°16/010 du 15 juillet 2016)", note: "« La capacité d'une personne d'engager ses services est régie par la loi du pays auquel elle appartient, ou à défaut de nationalité connue, par la loi congolaise. Au sens du présent code, la capacité de contracter est fixée à dix-huit ans sous réserve des dispositions suivantes : 1. Une personne âgée de 15 ans ne peut être engagée ou maintenue en service, même comme apprentie, que moyennant dérogation expresse du Président du Tribunal de paix, après avis psycho-médical d'un expert et de l'inspecteur du travail ; 2. Le Président du Tribunal de paix est saisi à la requête des parents ou de toute personne exerçant l'autorité parentale ou tutélaire sur l'enfant, par l'inspecteur du travail ou toute personne intéressée ; 3. Toutefois, l'opposition de l'inspecteur du travail et de l'autorité parentale ou tutélaire à la dérogation prévue au point 1 ci-dessus peut être levée par le Président du Tribunal de paix lorsque les circonstances ou l'équité le justifient ; »" },
      { type: 'paragraphe', texte: "La règle de conflit du premier alinéa est classique en droit international privé : la capacité relève de la loi nationale de la personne (loi personnelle), et à défaut de nationalité connue, de la loi congolaise. Elle signifie qu'un travailleur étranger dont la loi nationale fixe la majorité à vingt et un ans n'est capable de s'engager seul en RDC qu'à cet âge, sauf application de sa propre loi à l'émancipation. En pratique, la question se pose rarement, la plupart des législations retenant dix-huit ans. Le second alinéa fixe la capacité de contracter « au sens du présent code » à dix-huit ans. La formule est importante : la majorité civile congolaise est également fixée à dix-huit ans par le Code de la famille, mais le Code du travail pose sa propre règle, ce qui lui permet d'organiser des dérogations propres." },
      { type: 'paragraphe', texte: "Le premier régime dérogatoire concerne l'enfant de quinze ans. Il ne peut « être engagé ou maintenu en service, même comme apprentie », qu'en vertu d'une dérogation expresse du Président du Tribunal de paix, délivrée après un double avis : celui, psycho-médical, d'un expert, et celui de l'inspecteur du travail. La saisine du Président appartient aux parents ou à toute personne exerçant l'autorité parentale ou tutélaire, à l'inspecteur du travail ou à toute personne intéressée. Le point 3 introduit une soupape : l'opposition de l'inspecteur du travail et de l'autorité parentale peut être levée par le Président du Tribunal de paix « lorsque les circonstances ou l'équité le justifient », par exemple lorsque l'enfant est le seul soutien d'une fratrie orpheline. La dérogation est individuelle, motivée et révocable ; elle ne peut jamais couvrir un travail relevant des pires formes de l'article 3." },
      { type: 'paragraphe', texte: "Le deuxième régime concerne les adolescents de seize à moins de dix-huit ans : ils ne peuvent « être engagé[s] ou maintenu[s] en service que pour l'exécution des travaux légers et salubres prévus par un arrêté du Ministre ayant le travail et la prévoyance sociale dans ses attributions ». Ici, aucune autorisation judiciaire n'est requise, mais l'objet du travail est limité par une liste réglementaire. Cette liste est un texte d'application dont la vérification est indispensable avant toute embauche d'un mineur : un employeur qui confie à un adolescent de dix-sept ans un travail ne figurant pas sur la liste des travaux légers commet une infraction, même avec l'accord des parents. Entre quinze et seize ans, le texte est silencieux sur les travaux admis, ce qui conduit la doctrine à combiner les deux régimes : dérogation judiciaire et travaux légers." },
      { type: 'paragraphe', texte: "Les deux derniers alinéas règlent la preuve de l'âge et la sanction. « À défaut d'acte de naissance, le contrôle de l'âge du travailleur visé aux points 1 et 3 ci-dessus est exercé selon les modalités fixées par la Loi n° 87-010 du 1er août 1987 portant Code de la famille. » Dans un pays où une large part des naissances n'est pas déclarée à l'état civil, ce renvoi est loin d'être théorique : l'employeur qui engage un jeune travailleur sans acte de naissance doit recourir aux modes de preuve supplétifs du Code de la famille (jugement supplétif, attestation) et ne peut se contenter d'une déclaration verbale. Enfin, « toute forme de recrutement en violation des points 1 et 3 du présent article est interdite sur tout le territoire national » : la sanction est double, pénale pour l'employeur (Titre XV) et civile pour le contrat, qui est nul, sans que la nullité prive l'enfant de la rémunération du travail fourni." },
      { type: 'tableau', tableau: { entetes: ['Âge', 'Engagement possible ?', 'Conditions'], lignes: [
        ["Moins de 15 ans", "Non", "Interdiction absolue (art. 6 ; loi n°09/001)"],
        ["15 ans", "Exceptionnellement", "Dérogation expresse du Président du Tribunal de paix, après avis psycho-médical d'un expert et avis de l'inspecteur du travail ; même comme apprenti"],
        ["16 à moins de 18 ans", "Oui, pour certains travaux", "Travaux légers et salubres figurant sur la liste fixée par arrêté ministériel"],
        ["18 ans et plus", "Oui", "Pleine capacité au sens du Code ; loi nationale pour l'étranger"],
      ] } },
      { type: 'paragraphe', texte: "L'article 6 est au centre d'une critique constitutionnelle récente. La proposition de loi déposée le 28 mai 2025 par le député Éric Tshikuma relève que le Code confie au Tribunal de paix la compétence sur la capacité de l'enfant, alors que la loi n°09/001 du 10 janvier 2009 portant protection de l'enfant a créé le Tribunal pour enfants et lui a attribué la compétence en matière de protection de l'enfant, ce qui crée une incompatibilité entre les deux textes. La proposition entend harmoniser les compétences. En l'état du droit positif, le texte de l'article 6 demeure applicable, mais l'étudiant doit connaître cette tension : elle illustre la règle selon laquelle une loi spéciale postérieure peut affecter l'application d'une disposition antérieure sans l'abroger expressément, et la nécessité, pour le praticien, de vérifier devant quelle juridiction la dérogation doit être sollicitée dans le ressort concerné." },
      { type: 'paragraphe', texte: "Une dernière question de capacité mérite d'être signalée, bien qu'elle ne relève plus de l'article 6 : celle de la femme mariée. Sous l'empire du Code de la famille de 1987, la femme mariée devait obtenir l'autorisation de son mari pour accomplir les actes juridiques, ce qui a longtemps fragilisé la validité des contrats de travail conclus par des épouses sans l'accord de leur conjoint. La loi n°16/008 du 15 juillet 2016 modifiant le Code de la famille, adoptée le même jour que la réforme du Code du travail, a réformé ce régime, de sorte que la capacité de la travailleuse ne dépend plus de l'autorisation maritale. L'article 1er du Code, qui vise « l'état civil » parmi les critères d'indifférence, en tire la conséquence : le statut matrimonial du travailleur ou de la travailleuse est sans incidence sur l'application du Code." },
      { type: 'controle', question: {
        id: 'ctrl-1-7', question: "Un restaurateur de Goma souhaite engager un jeune de dix-sept ans comme aide de cuisine. Que doit-il vérifier ?",
        options: [
          { id: 'a', texte: "Rien de particulier : à seize ans révolus, le mineur a la pleine capacité de contracter" },
          { id: 'b', texte: "Obtenir une dérogation du Président du Tribunal de paix après avis psycho-médical" },
          { id: 'c', texte: "Que le poste correspond à un travail léger et salubre figurant sur la liste fixée par arrêté ministériel" },
          { id: 'd', texte: "Obtenir l'accord écrit de l'inspecteur du travail, qui remplace l'autorisation parentale" },
          { id: 'e', texte: "Que le jeune est émancipé par mariage, seule hypothèse où un mineur peut travailler" },
        ],
        reponseCorrecte: 'c', articleRef: "Art. 6",
        explication: "Entre seize et moins de dix-huit ans, aucune autorisation judiciaire n'est requise, mais le mineur ne peut être engagé que pour les travaux légers et salubres prévus par arrêté ministériel. La dérogation judiciaire concerne l'enfant de quinze ans.",
      } },
    ],
  },
  {
    numero: '1.8',
    titre: "Les définitions légales de l'article 7",
    navLabel: '1.8 Définitions légales',
    blocs: [
      { type: 'paragraphe', texte: "L'article 7, modifié en 2016, fixe onze définitions qui conditionnent l'interprétation de l'ensemble du Code. La méthode est celle du législateur moderne : plutôt que de laisser au juge le soin de dégager le sens des mots, la loi les définit elle-même, et ces définitions s'imposent à toutes les dispositions qui les emploient. Les plus structurantes pour la suite du manuel sont le travailleur, l'employeur, le contrat de travail et la rémunération, notion reprise telle quelle au chapitre 5 et mobilisée dans le calcul du décompte final au chapitre 10. Les autres n'en conditionnent pas moins la lecture de plusieurs chapitres ultérieurs." },
      { type: 'carte', titre: "Article 7, points 1 à 3 : les trois définitions cardinales", note: "« 1. Travailleur : toute personne physique en âge de contracter, quels que soient son sexe, son état civil et sa nationalité, qui s'est engagée à mettre son activité professionnelle, moyennant rémunération, sous la direction et l'autorité d'une personne physique ou morale, publique ou privée, dans les liens d'un contrat de travail. Pour la détermination de la qualité de travailleur, il ne sera tenu compte ni du statut juridique de l'employeur ni celui de l'employé. 2. Employeur : toute personne physique ou morale, de droit public ou privé, qui utilise les services d'un ou de plusieurs travailleurs en vertu d'un contrat de travail. 3. Contrat de travail : toute convention, écrite ou verbale, par laquelle une personne, le travailleur, s'engage à fournir à une autre personne, l'employeur, un travail manuel ou autre sous la direction et l'autorité directe ou indirecte de celui-ci et moyennant rémunération. »" },
      { type: 'paragraphe', texte: "Ces trois définitions se répondent. Le travailleur est nécessairement une personne physique : une société ne peut pas être « travailleur », ce qui distingue le contrat de travail de la sous-traitance. Il doit être « en âge de contracter », ce qui renvoie à l'article 6. Il met « son activité professionnelle » à disposition, et non un résultat : c'est la différence avec l'entrepreneur, qui promet un ouvrage. Il le fait « moyennant rémunération » : le bénévole n'est pas un travailleur. Enfin, il le fait « sous la direction et l'autorité » d'autrui : c'est le lien de subordination, critère décisif étudié à la section suivante. L'employeur, lui, peut être une personne physique ou morale, de droit public ou privé ; la précision selon laquelle il n'est tenu compte « ni du statut juridique de l'employeur ni celui de l'employé » confirme qu'une association sans but lucratif, une église, un parti politique ou une ambassade peuvent être employeurs au sens du Code. Le contrat de travail, enfin, peut être « écrite ou verbale » : l'écrit n'est pas une condition de validité, mais, comme le chapitre 3 le montrera, une condition de preuve et une obligation dont l'inobservation est sanctionnée." },
      { type: 'paragraphe', texte: "L'expression « sous la direction et l'autorité directe ou indirecte » mérite un mot. L'autorité peut être indirecte lorsqu'elle s'exerce par l'intermédiaire d'une hiérarchie, d'un chef d'équipe ou d'un système technique. Cette précision, ajoutée en 2016, anticipe les formes contemporaines d'organisation du travail : le contrôle par une application numérique ou par des indicateurs de performance est une forme d'autorité indirecte, et non l'absence d'autorité." },
      { type: 'carte', titre: "Article 7, points 4 à 7 : entreprise, établissement, recrutement, apprentissage", note: "« 4. Entreprise : toute organisation économique, sociale, culturelle, communautaire, philanthropique, de forme juridique déterminée, propriété individuelle ou collective, poursuivant ou non un but lucratif pouvant comprendre un ou plusieurs établissements. 5. Établissement : un centre d'activité individualisé dans l'espace ayant au point de vue technique son objet propre et utilisant les services d'un ou de plusieurs travailleurs qui exécutent une tâche sous une direction unique. Un établissement donné relève toujours d'une entreprise. Un établissement unique et indépendant constitue à la fois une entreprise et un établissement. 6. Recrutement : toute opération effectuée dans le but de s'assurer ou de procurer à autrui la main-d'œuvre des personnes n'offrant pas spontanément leurs services. 7. Contrat d'apprentissage : le contrat par lequel une personne physique ou morale, le maître d'apprentissage, s'oblige à donner ou à faire donner une formation professionnelle méthodique et complète à une personne, l'apprenti, et par lequel ce dernier s'oblige en retour à se conformer aux instructions qu'il recevra et à exécuter les ouvrages qui lui seront confiés en vue de son apprentissage. »" },
      { type: 'paragraphe', texte: "La distinction entre entreprise et établissement commande l'application de nombreux seuils du Code : élection des délégués du personnel, comité de sécurité et d'hygiène, service médical, règlement d'entreprise. L'entreprise est l'unité juridique et économique, définie très largement (le but lucratif est indifférent, ce qui inclut les ONG, les écoles privées et les confessions religieuses) ; l'établissement est l'unité technique et géographique. Une banque qui possède un siège à Kinshasa et des agences à Matadi, Kisangani et Bukavu est une entreprise comptant plusieurs établissements ; chacun a « son objet propre » et une « direction unique ». La définition du recrutement, quant à elle, vise l'opération par laquelle on va chercher la main-d'œuvre « n'offrant pas spontanément » ses services : elle fonde la réglementation des bureaux de placement et l'intervention de l'ONEM. Un arrêté du ministre de l'Emploi du 9 octobre 2025 (n°075/CAB/MIN.ET/FMM/RK/10/2025) est venu soumettre toute offre d'emploi à un visa préalable de l'ONEM avant publication, sous peine d'une amende administrative annoncée à cinq cents dollars par offre irrégulière : la définition de 2002 trouve ainsi une application réglementaire nouvelle, discutée au chapitre 8. Le contrat d'apprentissage, enfin, est défini ici pour être développé au Titre III (chapitre 2) : il se distingue du contrat de travail par son objet, la formation, l'apprenti s'obligeant à exécuter des ouvrages « en vue de son apprentissage » et non en vue d'une production." },
      { type: 'carte', titre: "Article 7, point 8 : la rémunération", note: "« Rémunération : la somme représentative de l'ensemble des gains susceptibles d'être évalués en espèces et fixés par un accord ou par les dispositions légales ou réglementaires qui sont dus en vertu d'un contrat de travail, par un employeur à un travailleur. Elle comprend notamment : le salaire ou traitement ; les commissions ; l'indemnité de vie chère ; les primes ; la participation aux bénéfices ; les sommes versées à titre de gratification ou de mois complémentaires ; les sommes versées pour prestations supplémentaires ; la valeur des avantages en nature ; l'allocation de congé ou l'indemnité compensatoire de congé ; les sommes payées par l'employeur pendant l'incapacité de travail et pendant la période précédant et suivant l'accouchement. Ne sont pas éléments de la rémunération : les soins de santé ; l'indemnité de logement ou le logement en nature ; les allocations familiales légales ; l'indemnité de transport ; les frais de voyage ainsi que les avantages accordés exclusivement en vue de faciliter au travailleur l'accomplissement de ses fonctions. »" },
      { type: 'paragraphe', texte: "Cette définition est la plus utilisée de tout le Code. Elle sert d'assiette au calcul de l'indemnité de préavis, des dommages-intérêts pour licenciement abusif, de l'allocation de congé, de la gratification et des cotisations sociales. Sa structure est binaire : une liste d'éléments inclus, introduite par « notamment » et donc non limitative, et une liste d'éléments exclus, limitative. Le critère qui sépare les deux est la contrepartie du travail : est rémunération ce qui rétribue la prestation ; n'en est pas ce qui rembourse un frais ou répond à un besoin social distinct (santé, logement, famille, transport). L'indemnité de logement, en particulier, est exclue alors qu'elle est obligatoire et souvent élevée, ce qui a une conséquence directe sur le décompte final : elle n'entre pas dans la base de calcul du préavis. Le décret n°25/22 du 30 mai 2025 fixe d'ailleurs, à côté du SMIG, les « allocations familiales minima » et la « contre-valeur du logement », c'est-à-dire précisément deux des éléments exclus de la rémunération par l'article 7." },
      { type: 'tableau', tableau: { entetes: ["Élément", "Rémunération ?", "Conséquence pratique"], lignes: [
        ["Salaire de base, traitement", "Oui", "Base du préavis, des congés, des cotisations"],
        ["Commissions, primes, participation aux bénéfices", "Oui", "Y compris les primes de rendement ou d'assiduité versées régulièrement"],
        ["Gratification, treizième mois", "Oui", "Une gratification qualifiée de libéralité mais versée avec régularité entre dans l'assiette"],
        ["Heures supplémentaires", "Oui", "« Sommes versées pour prestations supplémentaires »"],
        ["Avantages en nature (véhicule, nourriture)", "Oui, pour leur valeur", "À évaluer en espèces ; le logement en nature est en revanche exclu"],
        ["Allocation de congé, sommes payées pendant la maladie ou la maternité", "Oui", "La rémunération ne cesse pas pendant ces périodes"],
        ["Soins de santé", "Non", "Charge de l'employeur au titre du service médical (Titre VIII), hors assiette"],
        ["Indemnité de logement, logement en nature", "Non", "Obligatoire mais hors assiette ; contre-valeur fixée par décret"],
        ["Allocations familiales légales", "Non", "Prestation sociale, versée selon le nombre d'enfants (art. 7, point 11)"],
        ["Indemnité de transport, frais de voyage", "Non", "Remboursement de frais, non contrepartie du travail"],
      ] } },
      { type: 'paragraphe', texte: "Cette distinction, en apparence purement définitionnelle, alimente une part importante des litiges pratiques en matière de paie. Une gratification annuelle qualifiée de libérale par l'employeur, mais versée avec une régularité telle qu'elle en devient prévisible, tend en pratique à être requalifiée en élément de rémunération soumis aux cotisations sociales. Kiyana relève, à propos du contrat de travail en RDC, que la rédaction du contrat et des bulletins de paie gagne à anticiper cette distinction plutôt qu'à la découvrir lors d'un contentieux. À l'inverse, un employeur qui intitulerait « indemnité de transport » une somme sans lien avec un déplacement, dans le seul but de réduire l'assiette des cotisations, s'expose à une requalification par l'inspection du travail ou par la CNSS." },
      { type: 'carte', titre: "Article 7, points 9 à 11 : jour ouvrable, temps de services, famille du travailleur", note: "« 9. Jour ouvrable : chaque jour de la semaine à l'exception du jour de repos hebdomadaire et des jours fériés légaux. 10. Temps de services : le total des durées : des prestations de travail fournies chez le dernier employeur et chez les employeurs substitués pendant le dernier contrat et les contrats de travail précédents ; des congés y compris le congé de maternité ; de l'incapacité de travail, en cas d'accident du travail ou de maladie jusqu'à concurrence de six mois ininterrompus et sans limitation en cas d'accident du travail ou de maladie professionnelle ; des voyages se situant entre deux périodes des services. 11. Famille du travailleur : le conjoint ; les enfants tels que définis par la Loi n° 087-010 du 1er août 1987 portant Code de la famille ; les enfants que le travailleur a adoptés ; les enfants dont le travailleur a la tutelle ou la paternité juridique ; les enfants pour lesquels il est débiteur d'aliments conformément aux dispositions de la Loi n° 087-010 du 1er août 1987 portant Code de la famille. »" },
      { type: 'paragraphe', texte: "Le jour ouvrable est l'unité de compte du préavis et du congé annuel : dans une entreprise qui travaille du lundi au vendredi, une semaine compte cinq jours ouvrables, six si l'on travaille le samedi ; un jour férié légal tombant en semaine ne compte pas. Le temps de services, ou ancienneté, additionne non seulement les périodes de travail effectif, mais aussi les congés, y compris le congé de maternité, les périodes d'incapacité pour maladie ou accident (six mois au plus, sans limite s'il s'agit d'un accident du travail ou d'une maladie professionnelle) et les voyages entre deux périodes de service. Point essentiel : il cumule les prestations fournies « pendant le dernier contrat et les contrats de travail précédents » chez le même employeur ou chez les employeurs substitués. Deux contrats à durée déterminée successifs, ou un CDD suivi d'un CDI, forment un temps de services unique ; l'employeur ne remet pas l'ancienneté à zéro en changeant de contrat, ce qui pèse sur le calcul du préavis (art. 64) et du congé (art. 141)." },
      { type: 'paragraphe', texte: "La définition de la famille du travailleur commande les allocations familiales, les soins de santé, le logement et les frais de voyage. Elle vise le conjoint et cinq catégories d'enfants, dont les enfants adoptés et ceux pour lesquels le travailleur est débiteur d'aliments. Un enfant « entre en ligne de compte s'il est célibataire » et jusqu'à sa majorité en règle générale, jusqu'à vingt-cinq ans révolus « s'il étudie dans un établissement de plein exercice », et sans limite d'âge s'il est incapable d'exercer une activité lucrative en raison de son état physique ou mental et que le travailleur l'entretient. N'entre pas en ligne de compte « l'enfant mineur engagé dans les liens d'un contrat de travail ou d'apprentissage qui lui donne droit à une rémunération normale ». Le dernier alinéa de l'article 7 donne à cette définition une portée qui dépasse le Code : « dans tous les textes légaux et réglementaires relatifs à la sécurité sociale s'appliquant tant au secteur public qu'au secteur privé, le terme “enfant” doit être interprété conformément à l'article 7, point 11 », sans préjudice de dispositions plus favorables. C'est un exemple de définition-pivot, dont l'unité assure la cohérence entre le droit du travail et le droit de la sécurité sociale." },
    ],
  },
  {
    numero: '1.9',
    titre: "Le lien de subordination et la qualification du contrat de travail",
    navLabel: '1.9 Lien de subordination',
    blocs: [
      { type: 'paragraphe', texte: "La définition légale du contrat de travail met en avant un critère central : la subordination. C'est lui, et non la seule existence d'une rémunération, qui distingue le contrat de travail d'un contrat d'entreprise, d'un mandat, d'un contrat de société ou d'une convention de stage, distinction dont dépend l'accès au régime protecteur du Code. Un prestataire indépendant, aussi régulièrement rémunéré soit-il, n'est pas un travailleur au sens de l'article 7 s'il n'est pas placé sous l'autorité d'un employeur. À l'inverse, une personne qualifiée de « consultant » ou de « partenaire » par son contrat est un travailleur si les faits révèlent une subordination." },
      { type: 'paragraphe', texte: "Trois éléments constituent le contrat de travail : une prestation de travail, une rémunération et un lien de subordination. Les deux premiers se rencontrent dans bien d'autres contrats ; le troisième est propre au contrat de travail. La subordination se caractérise par l'exécution d'un travail sous l'autorité d'un employeur qui dispose du pouvoir de donner des ordres et des directives, d'en contrôler l'exécution et de sanctionner les manquements de son subordonné. Cette formule, dégagée par la jurisprudence sociale comparée (elle est reprise de manière constante par la chambre sociale de la Cour de cassation française, encore dans un arrêt du 13 septembre 2023), correspond exactement à l'expression « sous la direction et l'autorité directe ou indirecte » de l'article 7. Le juge du travail congolais ne s'arrête pas à une définition abstraite : il apprécie un faisceau d'indices concrets, dont aucun n'est à lui seul décisif." },
      { type: 'tableau', tableau: { entetes: ['Indice', 'Manifestation concrète', 'Poids'], lignes: [
        ["Pouvoir de direction", "L'employeur fixe les tâches, les méthodes, les objectifs et les priorités", "Fort"],
        ["Pouvoir de contrôle", "Vérification de l'exécution par une hiérarchie, un pointage, un reporting ou un système informatique", "Fort"],
        ["Pouvoir de sanction", "Avertissement, mise à pied, retenue, désactivation, exclusion", "Déterminant lorsqu'il est établi"],
        ["Intégration dans un service organisé", "Lieu, horaires, matériel et collègues imposés ; participation aux réunions", "Fort, sauf pour les métiers exercés hors les murs"],
        ["Absence de clientèle propre", "Le prestataire ne travaille que pour un donneur d'ordre et ne fixe pas ses prix", "Moyen"],
        ["Matériel fourni par l'entreprise", "Véhicule, outils, tenue, adresse électronique professionnelle", "Moyen"],
        ["Rémunération fixe et périodique", "Somme forfaitaire mensuelle indépendante du résultat", "Faible isolément, fort combiné aux autres"],
        ["Absence de risque économique", "Le prestataire ne supporte ni pertes ni investissements", "Moyen"],
      ] } },
      { type: 'paragraphe', texte: "Ce raisonnement par faisceau d'indices explique pourquoi la qualification donnée par les parties elles-mêmes au contrat, qu'elles l'aient appelé prestation de service, convention de consultance, contrat de partenariat ou convention de sous-traitance, ne lie pas le juge. Le principe est celui de la réalité : l'existence d'une relation de travail ne dépend ni de la volonté exprimée par les parties ni de la dénomination qu'elles ont donnée à leur convention, mais des conditions de fait dans lesquelles est exercée l'activité. Si les faits révèlent une subordination réelle, la relation sera requalifiée en contrat de travail, avec toutes les conséquences que cela emporte : affiliation à la CNSS, application du régime de préavis et de licenciement, droit aux congés payés, compétence du tribunal du travail. La requalification produit aussi des effets fiscaux et sociaux rétroactifs : cotisations et retenues sur toute la période, avec les pénalités de retard." },
      { type: 'paragraphe', texte: "La doctrine congolaise et comparée retient une série de distinctions pratiques. Dans le contrat d'entreprise, le prestataire s'engage sur un résultat, choisit librement ses moyens et supporte le risque de l'ouvrage ; il peut avoir plusieurs clients et facture un prix. Dans le mandat, le mandataire représente le mandant dans un acte juridique déterminé, sans lien de subordination ; le dirigeant social, mandataire de la société, n'est pas en principe un travailleur, sauf cumul d'un contrat de travail pour des fonctions techniques distinctes. Dans le contrat de société, les associés collaborent sur un pied d'égalité et partagent les bénéfices et les pertes ; l'affectio societatis exclut la subordination. Dans la convention de stage, l'objet est la formation et non la production, et l'absence de rémunération ou une simple indemnité n'exclut pas la requalification si le stagiaire occupe en réalité un poste de travail permanent. Dans le contrat d'apprentissage, la formation « méthodique et complète » est l'objet même du contrat, ce qui le soumet au Titre III plutôt qu'au Titre IV, mais l'apprenti reste protégé par les règles d'ordre public du Code." },
      { type: 'filet', titre: "Distinction pratique", texte: "Contrat de travail : l'employeur fixe les moyens et les méthodes, le travailleur exécute sous contrôle et peut être sanctionné. Contrat d'entreprise : le prestataire s'engage sur un résultat, en choisissant librement ses moyens, et supporte le risque. Mandat : le mandataire représente le mandant dans un acte juridique déterminé, sans lien de subordination. Société : les associés collaborent à égalité et partagent le risque." },
      { type: 'paragraphe', texte: "Les formes contemporaines d'organisation du travail renouvellent la question sans changer la méthode. Le travail par l'intermédiaire de plateformes numériques, qui se développe à Kinshasa et à Lubumbashi dans la livraison, le transport de personnes et les services à domicile, met en présence des « partenaires indépendants » qui possèdent leur véhicule et choisissent leurs horaires de connexion, mais qui reçoivent des instructions par l'application, sont notés par les clients, voient leur accès aux courses dépendre d'un algorithme et peuvent être désactivés. L'autorité « indirecte » de l'article 7 s'exerce ici par un système technique. La qualification dépend, comme toujours, du faisceau d'indices, et en particulier de l'existence d'un pouvoir de sanction : la désactivation pour refus de courses ou pour retard est une sanction, quel que soit le nom qu'on lui donne. Aucune décision publiée d'une juridiction congolaise ne tranche encore cette question à la date de rédaction ; les solutions comparées (requalification prononcée dans plusieurs pays européens, statut intermédiaire dans d'autres) constituent des éléments de réflexion, non des règles applicables en RDC." },
      { type: 'paragraphe', texte: "Sur le terrain de la preuve, le principe est que celui qui invoque l'existence d'un contrat de travail doit établir les faits qui caractérisent la subordination. Le contrat de travail pouvant être verbal (art. 7, point 3), la preuve est libre : témoignages, courriers électroniques, messages, plannings, bulletins de paie, badges, attestations de collègues. Lorsqu'un contrat écrit apparent existe (par exemple un contrat de prestation), il ne crée qu'une présomption simple que le travailleur peut renverser par tout moyen. L'inspecteur du travail, saisi d'une plainte, peut constater les conditions réelles d'exécution du travail et dresser un rapport qui pèsera lourd devant le tribunal du travail. À l'inverse, l'employeur qui soutient qu'un travailleur déclaré n'était en réalité qu'un prestataire se heurte à ses propres documents : bulletins de paie, déclarations à la CNSS, mentions au registre du personnel." },
      { type: 'controle', question: {
        id: 'ctrl-1-9', question: "Un contrat intitulé « convention de consultance » prévoit une rémunération mensuelle fixe, un horaire imposé de 8 h à 17 h, un bureau dans les locaux de la société et l'obligation de rendre compte chaque semaine au directeur, qui peut mettre fin à la convention « en cas de manquement ». Quelle est la qualification probable ?",
        options: [
          { id: 'a', texte: "Un contrat d'entreprise, puisque les parties l'ont intitulé « consultance »" },
          { id: 'b', texte: "Un contrat de travail, car le faisceau d'indices révèle direction, contrôle et pouvoir de sanction" },
          { id: 'c', texte: "Un mandat, car le consultant représente la société" },
          { id: 'd', texte: "Un contrat de société, en raison de la rémunération fixe" },
          { id: 'e', texte: "Aucune qualification n'est possible sans écrit signé par l'inspecteur du travail" },
        ],
        reponseCorrecte: 'b', articleRef: "Art. 7, point 3",
        explication: "Horaire imposé, intégration dans les locaux, reporting hebdomadaire et faculté de rupture pour manquement caractérisent la direction, le contrôle et la sanction. La dénomination choisie par les parties ne lie pas le juge ; la relation sera requalifiée en contrat de travail.",
      } },
    ],
  },
  {
    numero: '1.10',
    titre: "Actualités et perspectives de réforme (2025-2026)",
    navLabel: '1.10 Actualités et réformes',
    blocs: [
      { type: 'paragraphe', texte: "Le droit du travail congolais connaît, depuis 2025, une activité normative et parlementaire soutenue. Cette section en dresse l'état à la date de rédaction, en distinguant soigneusement les textes en vigueur des initiatives en cours. Elle sera actualisée au fil des chapitres suivants, chacun revenant sur les évolutions propres à son objet." },
      { type: 'paragraphe', texte: "La première actualité est réglementaire et concerne le salaire minimum. Le SMIG était resté fixé à 7 075 francs congolais par jour depuis 2018, montant que l'inflation avait vidé de toute portée. Le décret n°25/22 du 30 mai 2025 portant fixation du salaire minimum interprofessionnel garanti, des allocations familiales minima et de la contre-valeur du logement, signé par la Première ministre Judith Suminwa et contresigné par le ministre de l'Emploi et du Travail, a fixé le SMIG du manœuvre ordinaire à 21 500 francs congolais par jour, en deux paliers : 14 500 francs à compter de la paie de mai 2025, puis 21 500 francs à compter de la paie de janvier 2026. Le décret maintient la tension salariale de un à dix entre le manœuvre ordinaire et le cadre de collaboration, et fixe les allocations familiales minima et la contre-valeur du logement par référence au SMIG. Ce relèvement, de l'ordre de 204 % par rapport à 2018, a été salué par les organisations syndicales lors de la fête du travail du 1er mai 2025, tandis que les employeurs plaidaient pour une application progressive ; au 1er mai 2026, le SMIG de 21 500 francs était en vigueur, et les syndicats le jugeaient encore insuffisant au regard du coût de la vie. Le chapitre 5 étudie en détail le régime du SMIG et son calcul." },
      { type: 'paragraphe', texte: "La deuxième actualité est parlementaire. Le 28 mai 2025, le député national Éric Tshikuma Mwimbayi a déposé à l'Assemblée nationale une proposition de loi modifiant et complétant le Code du travail. Son exposé des motifs relève plusieurs incohérences entre le Code de 2002 et la Constitution de 2006 : le Code renvoie encore à des décrets du Président de la République pour des matières d'exécution qui relèvent désormais du Premier ministre, en méconnaissance du bicéphalisme de l'exécutif ; il attribue au Tribunal de paix une compétence sur la capacité de l'enfant que la loi n°09/001 confie au Tribunal pour enfants ; il conserve des dispositions jugées discriminatoires selon le sexe ou l'âge. La proposition entend aligner le Code sur la Constitution, garantir sa cohérence avec les autres lois et renforcer la protection des travailleurs. Le 15 mai 2026, une seconde proposition, déposée par le député Prince Kangila Kawele, vise à instituer un régime spécifique du travail domestique, avec contrat écrit, salaire minimum, affiliation à la sécurité sociale et accès aux soins ; elle a été contestée par le syndicat LA CLÉ, pour qui les domestiques relèvent déjà du Code et souffrent d'un défaut d'application, non d'un vide juridique." },
      { type: 'paragraphe', texte: "La troisième actualité est internationale. Le projet de loi autorisant la ratification de la convention n°190 de l'OIT sur la violence et le harcèlement dans le monde du travail, déposé au Sénat le 7 avril 2025, ouvrirait, s'il aboutissait, une obligation d'adopter une législation interne définissant et interdisant la violence et le harcèlement au travail, y compris fondés sur le genre, et d'organiser des mécanismes de plainte et de protection. Le Code actuel ne comporte pas de définition du harcèlement ; la ratification imposerait donc une modification législative, probablement dans le Titre VI sur les conditions générales de travail ou dans le Titre XII sur les relations professionnelles." },
      { type: 'paragraphe', texte: "La quatrième actualité concerne l'administration de l'emploi. L'arrêté ministériel du 9 octobre 2025 soumettant toute offre d'emploi au visa préalable de l'ONEM, sous peine d'amende administrative, et le contrat-programme de performance signé pour l'exercice 2026 par les institutions publiques de l'emploi et de la formation professionnelle, traduisent une volonté de formaliser le marché du travail et de lutter contre les offres frauduleuses. Ces mesures s'inscrivent dans le droit fil de la définition du recrutement de l'article 7 et des missions de l'ONEM fixées au Titre IX, étudié au chapitre 8." },
      { type: 'tableau', tableau: { entetes: ['Initiative', 'Date', 'Statut à la rédaction', 'Portée pour ce chapitre'], lignes: [
        ["Décret n°25/22 (SMIG 21 500 FC/jour, allocations familiales minima, contre-valeur du logement)", "30 mai 2025", "En vigueur ; second palier appliqué depuis janvier 2026", "Source réglementaire (niveau 4) ; illustration des éléments exclus de la rémunération"],
        ["Proposition de loi Tshikuma (cohérence constitutionnelle du Code)", "28 mai 2025", "Déposée ; non adoptée", "Critique de l'art. 6 (Tribunal de paix) et du renvoi aux décrets présidentiels"],
        ["Projet de loi de ratification de la convention OIT n°190", "7 avril 2025", "Déposé au Sénat ; non adopté", "Hiérarchie des normes : une convention non ratifiée ne produit pas d'effet interne"],
        ["Arrêté n°075 (visa ONEM des offres d'emploi)", "9 octobre 2025", "En vigueur", "Application de la définition du recrutement (art. 7, point 6)"],
        ["Proposition de loi Kangila (travail domestique)", "15 mai 2026", "Déposée ; contestée ; non adoptée", "Champ d'application de l'art. 1er"],
      ] } },
      { type: 'paragraphe', texte: "Ces évolutions appellent une méthode. L'étudiant et le praticien doivent, pour chaque question, identifier le texte en vigueur à la date des faits, vérifier s'il a été modifié par un texte postérieur, et distinguer ce qui relève du droit positif de ce qui relève du projet ou du plaidoyer. Un devoir ou une consultation qui présenterait la proposition Tshikuma comme une loi applicable, ou la convention n°190 comme ratifiée, serait juridiquement faux, même si le fond de la réforme est pertinent. C'est cette discipline de vérification, plus que la mémorisation des chiffres, qui fait le juriste du travail." },
      { type: 'paragraphe', texte: "Enfin, le contexte économique donne à toutes ces règles leur mesure. Le taux d'emploi moyen de 55,9 % relevé par l'INS, la prépondérance de l'agriculture et du commerce, l'importance de l'économie informelle et le niveau du SMIG, équivalent à environ neuf dollars par jour, rappellent que le droit du travail codifié ne régit directement qu'une fraction de la population active. Sa fonction n'en est pas moins décisive : il fixe la norme de référence vers laquelle les politiques de formalisation, l'inspection du travail et les partenaires sociaux tendent, et il protège effectivement les travailleurs du secteur formel, public et privé, qui en relèvent." },
    ],
  },
]

